INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''yarn dyeing'' (dyeing yarn packages/hanks before weaving or knitting) primarily used to produce?', '["Fabrics with woven-in patterns like stripes, checks, or plaids, where different colored yarns are arranged during weaving/knitting","Only solid white fabric with absolutely no color variation","Fabric that is later re-dyed entirely a solid color, erasing the yarn-dyed pattern","A method used exclusively for synthetic fiber, never natural fiber"]'::jsonb, 'Fabrics with woven-in patterns like stripes, checks, or plaids, where different colored yarns are arranged during weaving/knitting', 'Yarn dyeing colors yarn (as hanks, packages, or beams) before fabric formation, allowing different colored yarns to be arranged in the warp/weft or knit structure to create woven-in patterns like stripes, checks, plaids, or Jacquard-style designs that piece dyeing (coloring the finished fabric) cannot replicate.', 1, '{"yarn-dyeing"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''package dyeing'' as a specific method of yarn dyeing?', '["Dyeing yarn wound onto perforated packages (cones/cheeses), with dye liquor forced to circulate through the package for penetration","A method that dyes only loose, unwound fiber, never yarn on any package","A synonym for garment dyeing, unrelated to yarn preparation","A method that applies dye only via printing screens, with no liquor circulation"]'::jsonb, 'Dyeing yarn wound onto perforated packages (cones/cheeses), with dye liquor forced to circulate through the package for penetration', 'Package dyeing winds yarn onto special perforated packages (spring cones or cheeses), then loads them into a dyeing vessel where dye liquor is pumped to circulate radially through the porous package, penetrating and dyeing the yarn evenly.', 1, '{"package-dyeing"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'Why must yarn be wound at a carefully controlled, consistent DENSITY for package dyeing to achieve even results?', '["Uneven package density creates areas of differing resistance to liquor flow, causing some yarn layers to receive more/less dye circulation and resulting in uneven (inside-vs-outside) shade","Package density has no relationship to dye liquor flow or shade evenness at all","Denser packages always dye lighter than looser packages, with no relationship to flow resistance","Package density only matters for garment dyeing, never for yarn package dyeing"]'::jsonb, 'Uneven package density creates areas of differing resistance to liquor flow, causing some yarn layers to receive more/less dye circulation and resulting in uneven (inside-vs-outside) shade', 'If a package is wound too tightly in some areas and loosely in others, dye liquor flows preferentially through the looser, lower-resistance paths, starving the tighter areas of adequate circulation — causing visible shade variation between different parts of the same package (or between inside and outside layers).', 2, '{"package-density","package-dyeing"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is ''beam dyeing'' as a yarn (or warp) dyeing method?', '["Yarn (often warp) is wound onto a perforated beam and dye liquor is circulated through it, similar in principle to package dyeing but using a beam format","A method that dyes only finished woven fabric, with no relation to yarn preparation","A synonym for garment dyeing performed inside a rotating drum","A method that uses no liquor circulation, relying only on surface spraying"]'::jsonb, 'Yarn (often warp) is wound onto a perforated beam and dye liquor is circulated through it, similar in principle to package dyeing but using a beam format', 'Beam dyeing winds yarn (frequently warp yarn intended for weaving) onto a large perforated beam, then circulates dye liquor through the beam similarly to package dyeing — a practical method for dyeing warp yarn efficiently in bulk before it goes to weaving.', 2, '{"beam-dyeing"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'basic', 'multiple_choice', 'What is ''space dyeing'' of yarn intended to create?', '["A single yarn with multiple colors appearing along its length at intervals, creating a variegated, multicolor effect in the resulting fabric","A yarn dyed a single uniform color with zero variation along its length","A finishing technique applied only after the fabric is completely woven","A dyeing method that can only be used on already-woven fabric, never on yarn directly"]'::jsonb, 'A single yarn with multiple colors appearing along its length at intervals, creating a variegated, multicolor effect in the resulting fabric', 'Space dyeing applies different colors to different sections along a single continuous yarn''s length (often via a print-like or space-dye machine), creating a variegated, multi-color effect when that yarn is later knitted or woven into fabric.', 1, '{"space-dyeing"}'::text[]),
('9e3b3072-3153-414d-b2d7-1bf0789002ac', 'intermediate', 'multiple_choice', 'What is the purpose of a ''dye fixative'' (or fixing agent) sometimes applied as a post-treatment after dyeing (in addition to the primary fixation chemistry of the dye class itself)?', '["To further improve wash/wet fastness by forming an additional protective/binding layer over the dye already on the fiber","To completely remove all dye from the fabric surface","To apply the initial base color before any main dyeing step","To reduce the fabric''s overall fiber content"]'::jsonb, 'To further improve wash/wet fastness by forming an additional protective/binding layer over the dye already on the fiber', 'Post-dyeing fixative treatments (e.g., cationic fixing agents for direct or reactive dyes) can form an additional layer/complex over the dyed fiber, further reducing dye bleeding and improving wet/wash fastness beyond what the base dye class chemistry alone achieves.', 2, '{"dye-fixative"}'::text[]);
